package cmd

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/spf13/cobra"

	"github.com/plane-cli/plane-cli/internal/config"
)

func newConfigCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "config",
		Short: "Manage CLI configuration",
	}

	cmd.AddCommand(newConfigInitCmd())
	cmd.AddCommand(newConfigSetCmd())
	cmd.AddCommand(newConfigGetCmd())
	cmd.AddCommand(newConfigListCmd())

	return cmd
}

func newConfigInitCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "init",
		Short: "Initialize configuration interactively",
		RunE: func(cmd *cobra.Command, args []string) error {
			reader := bufio.NewReader(os.Stdin)

			// Base URL (required for self-hosted)
			fmt.Print("Plane instance URL (e.g., https://plane.example.com): ")
			baseURL, _ := reader.ReadString('\n')
			baseURL = strings.TrimSpace(baseURL)
			if baseURL == "" {
				return fmt.Errorf("base URL is required for self-hosted instances")
			}

			// API Key
			fmt.Print("API key: ")
			apiKey, _ := reader.ReadString('\n')
			apiKey = strings.TrimSpace(apiKey)
			if apiKey == "" {
				return fmt.Errorf("API key is required")
			}

			// Workspace (optional)
			fmt.Print("Default workspace slug (optional): ")
			ws, _ := reader.ReadString('\n')
			ws = strings.TrimSpace(ws)

			// Project (optional)
			fmt.Print("Default project ID (optional): ")
			proj, _ := reader.ReadString('\n')
			proj = strings.TrimSpace(proj)

			cfg := &config.Config{
				BaseURL:   strings.TrimRight(baseURL, "/"),
				APIKey:    apiKey,
				Workspace: ws,
				Project:   proj,
				Format:    "json",
			}

			if err := config.Save(cfg); err != nil {
				return fmt.Errorf("saving config: %w", err)
			}

			fmt.Printf("Configuration saved to %s\n", config.FilePath())
			return nil
		},
	}
}

func newConfigSetCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "set <key> <value>",
		Short: "Set a config value",
		Long:  "Valid keys: " + strings.Join(config.ValidKeys(), ", "),
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := config.Set(args[0], args[1]); err != nil {
				return err
			}
			fmt.Printf("Set %s = %s\n", args[0], args[1])
			return nil
		},
	}
}

func newConfigGetCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "get <key>",
		Short: "Get a config value",
		Long:  "Valid keys: " + strings.Join(config.ValidKeys(), ", "),
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			val, err := config.Get(args[0])
			if err != nil {
				return err
			}
			if val == "" {
				fmt.Println("(not set)")
			} else {
				fmt.Println(val)
			}
			return nil
		},
	}
}

func newConfigListCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "list",
		Short: "List all config values",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load("")
			if err != nil {
				return err
			}

			fmt.Printf("base_url:  %s\n", maskEmpty(cfg.BaseURL))
			fmt.Printf("api_key:   %s\n", maskAPIKey(cfg.APIKey))
			fmt.Printf("workspace: %s\n", maskEmpty(cfg.Workspace))
			fmt.Printf("project:   %s\n", maskEmpty(cfg.Project))
			fmt.Printf("format:    %s\n", maskEmpty(cfg.Format))
			fmt.Printf("\nConfig file: %s\n", config.FilePath())
			return nil
		},
	}
}

func maskAPIKey(key string) string {
	if key == "" {
		return "(not set)"
	}
	if len(key) <= 8 {
		return "****"
	}
	return key[:4] + "..." + key[len(key)-4:]
}

func maskEmpty(s string) string {
	if s == "" {
		return "(not set)"
	}
	return s
}

