// Look up the issue by scanning pages for matching sequence_id.
// Plane API does not support filtering by sequence_id as a query parameter.
cursor := ""
for {
	p := api.NewPath("workspaces/{workspace_slug}/projects/{project_id}/work-items/").
		Workspace(ws).Project(projectID).
		QueryInt("per_page", 100)
	if cursor != "" {
		p.Query("cursor", cursor)
	}

	path, err := p.Build()
	if err != nil {
		return "", err
	}

	resp, err := client.Get(path)
	if err != nil {
		return "", fmt.Errorf("looking up %s: %w", issueRef, err)
	}

	var paginated struct {
		Results []struct {
			ID         string `json:"id"`
			SequenceID int    `json:"sequence_id"`
		} `json:"results"`
		NextPage   bool   `json:"next_page_results"`
		NextCursor string `json:"next_cursor"`
	}
	if err := json.Unmarshal(resp, &paginated); err == nil {
		for _, item := range paginated.Results {
			if item.SequenceID == seqNum {
				return item.ID, nil
			}
		}
		if !paginated.NextPage || paginated.NextCursor == "" {
			break
		}
		cursor = paginated.NextCursor
		continue
	}

	// Fallback: try direct array
	var issues []struct {
		ID         string `json:"id"`
		SequenceID int    `json:"sequence_id"`
	}
	if err := json.Unmarshal(resp, &issues); err == nil {
		for _, item := range issues {
			if item.SequenceID == seqNum {
				return item.ID, nil
			}
		}
	}
	break
}

return "", fmt.Errorf("issue %s not found", issueRef)

